class EulerFunction:
    def __init__(self):
        self.cache = [1] * (MAX_N + 1)

    def phi(self, n):
        if n <= 1:
            return 1
        divisors = get_divisors(self.cache, n)
        result = n
        for divisor in divisors:
            if n % divisor == 0:
                result = (result * (divisor - 1)) // divisor
                while n % divisor == 0:
                    n //= divisor
        return result * (n == 1)

def get_divisors(cache, n):
    divisors = []
    i = 1
    while i ** 2 <= n:
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
        else:
            i += 1
    divisors.sort()
    for index in range(len(divisors) - 1, -1, -1):
        cache[divisors[index]] += index
    return divisors

