import math

def beauty(N, A):
    val = 0
    for i in range(1, N-1):
        for j in range(i+1, N):
            if A[i] < A[j]:
                val += 1
            else:
                val -= 1
    return val

def expected_beauty(N, edges):
    total_beauty = 0
    for edge in edges:
        # Assuming edge (a, b), calculate beauty for BFS starting at 'a'
        a, b = edge
        bottom_edges = [edge for edge in edges if not (edge[0] == a and edge[1] == b)]
        if len(bottom_edges) == 0:
            total_beauty += beauty(N, A[:a] + A[a+1:]) + beauty(N, A[:b] + A[b+1:])
        else:
            sub_total_beauty = 0
            for bottom_edge in bottom_edges:
                internal_edges = [[b, x] for x in A if x not in bottom_edge[:-1]]
                for internal_edge in internal_edges:
                    beauty_val = beauty(N, A[:bottom_edge[1]] + A[internal_edge] + A[internal_edge+1:] + A[bottom_edge:[1]])
                    # Inserting new edge costs simplicity and performance
                    sub_total_beauty += beauty_val
                    break
            total_beauty += sub_total_beauty
    return total_beauty / len(edges)

