    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            point = points[i] - points[j]
            if point[0] != point[1]:
                hist[int(point[0] + point[1])] += 1
    return hist

def count_good_lines(points):
    hist = count_points_histogram(points)
    pairs = count_points_pairs(points)

    result = 0
    for key in pairs.keys():
        if pairs[key] % 2 == 1 or key % 2 == 0:
            result += 1

    for x, y in points:
        for from_x, from_y in [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]:
            for to_x, to_y in [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]:
                if (x + from_x == 0 and y + from_y == 0) or (from_x * to_x + from_y * to_y == 0):
                    if (from_x * x + from_y * y != 0) and (to_x * x + to_y * y != 0):
                        hist[(from_x - to_x) + (from_y - to_y)] -= 1

    for key, value in hist.items():
        if value == 0 and key % 2 == 1:
