import math

def euler_phi(n):
    if n == 1:
        return 1

    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def process_queries(n, queries):
    result = [1] * n
    prefix_sums = [1] * (n + 1)

    for query in range(1, n + 1):
        li, ri = queries[query - 1]
        for k in range(li-1, ri):
            if k > 2:
                prefix_sums[k] = (prefix_sums[k-1] * (k-1)) % (10**9 + 7)
            result[k] = prefix_sums[k+1] * prefix_sums[li-1] * euler_phi(n) % (10**9 + 7)

    return result

