    n, m = map(int, input().split())
    groups = [0 for _ in range(t)]
    for _ in range(n):
        l, r = map(int, input().split())
        groups[l] = groups[r + 1] = 1
    class_attendance = [0 for _ in range(T + 1)]
    conflict_pairs = set()
    for _ in range(m):
        teacher1, teacher2 = map(int, input().split())
        class_attendance[teacher1], class_attendance[teacher2] = 1, 1
        conflict_pairs.add((teacher1, teacher2))
        conflict_pairs.add((teacher2, teacher1))
    frequency = defaultdict(list)
    for teacher, presence in enumerate(class_attendance):
        if presence == 1:
            for i in range(1, 1 + (r := presence // t) // t or 1):
                for j in range(t * i - (r - i), t * i - t + 1):
                    frequency[i] += [j]
    visited = defaultdict(lambda: defaultdict(bool))
    buffer = []
    for i in range(1, t + 1):
        heap = [(-len(buffer), i)]
        visited[i][0] = True
        while heap and i in buffer:
            _, level = heappop(heap)
            if level > 0:
                visited[i][level - 1] = True
                heappush(heap, (-len(buffer), i))
        while len(buffer) < len(groups):
            _, level = heappop(heap)
            for j in range(t):
                if visited[i][level]:
                    tuple = (j, t - j)
                    if tuple in conflict_pairs:
                        continue
                    if tuple[0] > tuple[1]:
                        flag = -1
                    else:
                        flag = 1
                    heappush(buffer, (flag * len(groups), j))
                    visited[i][t - j] = True
    if len(buffer) != t // 2:
        return 'IMPOSSIBLE'
    if len(groups) != t or len(buffer) != t // 2:
        return 'IMPOSSIBLE'
    for i, target in enumerate(groups):
        if target != buffer[i]:
            return 'IMPOSSIBLE'
    return 'POSSIBLE\n' + ' '.join(map(str, buffer))
