from math import factorial
from itertools import combinations

MOD = 998244353

def ncr(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

def solve(tree):
    n = len(tree) + 1
    g = [[] for _ in range(n)]

    for u, v in tree:
        g[u-1].append(v-1)
        g[v-1].append(u-1)

    ways = 0
    for r in range(0, n):
        if ncr(n, r) > 1: # Check if there's a way to form a maximum matching
            c_r = combinations(range(n), r)
            for comb in c_r:
                m = len(list(filter(lambda x: x in comb, g)))
                if m == n - r:
                    ways += 1
                    ways %= MOD
    return ways % MOD

if __name__ == "__main__":
