def parse_circuit(circuit_str):
    stack = []
    current_resistance = 0
    for char in circuit_str:
        if char == ' ':
            continue
        elif char == '*':
            stack.append((current_resistance, current_resistance))
            current_resistance = 0
        else:
            current_resistance += int(char)
    stack.append((current_resistance, current_resistance))

    circuit_dict = defaultdict(int)
    while stack:
        resistance, _ = stack.pop()
        if resistance == 0:
            continue
        circuit_dict[len(stack)] = resistance

    circuit_layout = [sum(circuits) for circuits in circuit_dict.values()]
    parallel_groups = set(reduce(lambda x, y: x + y, circuit_dict.values(), []))
    
    return circuit_layout, parallel_groups

