from collections import defaultdict

def find_resistances(r, circuit):
    components = defaultdict(int)
    n = len(circuit)
    for i in range(n):
        if i < n - 1 and circuit[i:i+2] == 'SP':
            components['S'] += 1
        elif i == n - 1 or circuit[i:i+2] == 'S*':
            components['*'] += 1

    components['S'] += circuit[:n-1].count('*') + components.get('*') or 0

    return min(components.values()) * (r - sum(components.values()))

def optimize_circuit(n, r, circuit):
    components = defaultdict(int)
    n = len(circuit)
    for i in range(n):
        if i < n - 1 and circuit[i:i+2] == 'SP':
            components['S'] += 1
        elif i == n - 1 or circuit[i:i+2] == 'S*':
            components['*'] += 1

    components['S'] += circuit[:n-1].count('*') + components.get('*') or 0

    if sum(components.values()) == n:
        return "REVOLTING " + ' '.join(str(2) for _ in range(n))

    best_cost, best_resistances = float('inf'), [2] * n

    for res1, res2, capacity1, capacity2 in [(0, float('inf'), float('inf'), 0), (1, 0, 0, float('inf'))]:
        resistances = [res1, res2] + [capacity1, capacity2]
        for i in range(1, n+1):
            rightres = min(components[i], i-1)
            wires_needed = rightres - resistances[i-1]

            available = capacity2 - leftres
            if wires_needed <= available:
                resistances[i] = wires_needed # { i, i-1 } + min{ available, available = wire_needed }
            elif wires_needed > available:
                break

        if sum(resistances) < best_cost:
            best_cost = sum(resistances)
            best_resistances = list(resistances[:])

    if best_cost == float('inf'):
        return "LOSS"

    return "REVOLTING " + ' '.join(str(x) for x in best_resistances)

